sys_script.script:
(function executeRule(current, previous) {

    try {
        gs.info("Business Rule Triggered for Event: " + current.number);

        var rm = new sn_ws.RESTMessageV2('Notify External Event System', 'Send Event Notification');

        rm.setStringParameterNoEscape('u_event_name', current.u_event_name ? current.u_event_name.toString() : '');
        rm.setStringParameterNoEscape('u_event_date', current.u_event_date ? current.u_event_date.toString() : '');
        rm.setStringParameterNoEscape('u_location', current.u_location ? current.u_location.toString() : '');
        rm.setStringParameterNoEscape('u_status', current.u_status ? current.u_status.toString() : '');
        rm.setStringParameterNoEscape('u_contact_person', current.u_contact_person ? current.u_contact_person.toString() : '');

        var response = rm.execute();
        var status = response.getStatusCode();
        var body = response.getBody();

        gs.info("Event Notification Sent. Status: " + status + ". Response: " + body);
    } catch (ex) {
        gs.error("Error sending event notification: " + ex.message);
    }

})(current, previous);
